mule:set-variable.value:
#[do {
                var t = upper(vars.storageType default 'S3')
                var auth = if (upper(vars.authMode default 'CLIENT_SECRET') == 'CERTIFICATE')
                               { certificateKeystore: vars.certificateKeystore, certificateKeystorePassword: vars.certificateKeystorePassword }
                           else { clientSecret: vars.clientSecret }
                var specific = if (t == 'ADLS') { adlsAccount: vars.adlsAccount, adlsContainer: vars.adlsContainer }
                               else { region: vars.region, signingHost: vars.signingHost, roleArn: vars.roleArn, stsRegion: vars.stsRegion }
                var missing = ({ gatewayHost: vars.gatewayHost, tenantId: vars.tenantId, clientId: vars.clientId } ++ auth ++ specific)
                              filterObject ((v) -> isEmpty(v)) pluck ($$ as String)
                ---
                if (t != 'S3' and t != 'ADLS') ['Storage type must be S3 or ADLS, got ' ++ (vars.storageType default '')]
                else if (isEmpty(missing)) []
                else ['Missing for storage type ' ++ t ++ ': ' ++ (missing joinBy ', ')]
            }]

http:request.http:body:
#[output application/x-www-form-urlencoded --- {
                        grant_type: 'client_credentials',
                        client_id: vars.clientId,
                        scope: vars.tokenScope
                    } ++ vars.clientAuth]

mule:set-payload.value:
#[output application/java --- {
                token: vars.accessToken,
                expiresAt: (now() + (('PT' ++ ((vars.entraBody scan /"expires_in"\s*:\s*"?(\d+)/)[0][1] default '3600') ++ 'S') as Period)) as String
            }]

mule:set-variable.value:
#[do {
                var code = vars.code
                var status = vars.statusCode as Number
                var fromStorage = code != null or !isEmpty(vars.requestId)
                ---
                if (!fromStorage and (status == 401 or status == 403)) 'GATEWAY_REJECTED'
                else if (['NoSuchKey', 'NoSuchBucket', 'NoSuchVersion', 'BlobNotFound', 'ContainerNotFound',
                          'ResourceNotFound', 'PathNotFound', 'FilesystemNotFound'] contains code) 'NOT_FOUND'
                else if (code == 'SignatureDoesNotMatch') 'SIGNATURE_MISMATCH'
                else if (['AccessDenied', 'AllAccessDisabled', 'AuthorizationPermissionMismatch', 'AuthorizationFailure',
                          'InsufficientAccountPermissions', 'AuthorizationSourceIPMismatch', 'AuthorizationProtocolMismatch'] contains code) 'ACCESS_DENIED'
                else if (['InvalidAccessKeyId', 'ExpiredToken', 'InvalidToken', 'TokenRefreshRequired',
                          'InvalidAuthenticationInfo', 'AuthenticationFailed'] contains code) 'INVALID_CREDENTIALS'
                else if (['XAmzContentSHA256Mismatch', 'BadDigest', 'Md5Mismatch'] contains code) 'BAD_DIGEST'
                else if (code == null and status == 404) 'NOT_FOUND'
                else if (code == null and status == 403) 'ACCESS_DENIED'
                else if (status >= 500) 'SERVER_ERROR'
                else 'BAD_REQUEST'
            }]

mule:set-payload.value:
#[output application/java --- {
                accessKeyId:     (vars.stsBody scan /<AccessKeyId>([^<]+)<\/AccessKeyId>/)[0][1],
                secretAccessKey: (vars.stsBody scan /<SecretAccessKey>([^<]+)<\/SecretAccessKey>/)[0][1],
                sessionToken:    (vars.stsBody scan /<SessionToken>([^<]+)<\/SessionToken>/)[0][1],
                expiresAt:       (vars.stsBody scan /<Expiration>([^<]+)<\/Expiration>/)[0][1]
            }]

#[output application/java --- {
                host: vars.adlsHost,
                path: '/' ++ vars.adlsContainer ++ '/' ++ ((vars.cleanKey splitBy '/') map dw::core::URL::encodeURIComponent($) joinBy '/'),
                headers: {
                    'Authorization': 'Bearer ' ++ vars.token,
                    'x-ms-version': if (isEmpty(vars.adlsApiVersion)) '2021-08-06' else vars.adlsApiVersion,
                    'x-ms-date': (now() >> 'UTC') as String { format: "EEE, dd MMM yyyy HH:mm:ss 'GMT'", locale: 'en' }
                } ++ (({ (vars.hostNameHeader default ''): vars.adlsHost,
                         (vars.accessIdHeader default ''): vars.accessId default '',
                         (vars.accessSecretHeader default ''): vars.accessSecret default '' })
                      filterObject ((v, k) -> !isEmpty(k as String) and !isEmpty(v)))
            }]

http:request.http:headers:
#[vars.req.headers
                        ++ { 'x-ms-blob-type': 'BlockBlob', 'Content-Type': vars.contentType }
                        ++ ((vars.userMetadata default {}) mapObject ((v, k) -> { ('x-ms-meta-' ++ (k as String)): v as String }))]
